CREATE TABLE institutional_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL, match_id uuid NOT NULL, status text NOT NULL DEFAULT 'pending_authorization', authorized_by text, authorized_at timestamptz, submitted_at timestamptz, received_at timestamptz, decision_at timestamptz, outcome text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,match_id));